class BackToTop extends HTMLElement{constructor(){super(),this.btn=this,window.addEventListener("scroll",(()=>{window.scrollY>400?(this.btn.style.display="flex",this.btn.style.opacity="1"):(this.btn.style.opacity="0",setTimeout((()=>{window.scrollY<=400&&(this.btn.style.display="none")}),300))})),this.addEventListener("click",(t=>{t.preventDefault(),window.scrollTo({top:0,behavior:"smooth"})}))}}customElements.define("back-to-top",BackToTop);